package android.os;
public class Handler {static java.util.List<Runnable> posted=new java.util.ArrayList<>();private Looper looper;public Handler(Looper l){looper=l;}public Looper getLooper(){return looper;}public static Handler createAsync(Looper l){return new Handler(l);}public boolean post(Runnable r){posted.add(r);return true;}public boolean postDelayed(Runnable r,long d){return true;}public void removeCallbacks(Runnable r){posted.remove(r);}public static void runPosted(){java.util.List<Runnable> work=new java.util.ArrayList<>(posted);posted.clear();for(Runnable r:work)r.run();}}
